def solve():
    input_str = sys.stdin.read().strip()
    if not input_str:
        return ''

    lines = input_str.split('\n')
    n, m = map(int, lines[0].split())

    if m == n - 1:
        return ''

    edges = []
    for i in range(m):
        parts = lines[i + 1].split()
        u, v, e = map(int, parts)
        edges.append((e, u - 1, v - 1, i))

    # Sort by weight
    sorted_edges = sorted(edges)

    # Kruskal's for MST
    parent = list(range(n))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx != ry:
            parent[rx] = ry
            return True
        return False

    mst_adj = [[] for _ in range(n)]
    mst_indices = set()

    for e, u, v, idx in sorted_edges:
        if union(u, v):
            mst_adj[u].append((v, e))
            mst_adj[v].append((u, e))
            mst_indices.add(idx)

    # Binary lifting for tree queries
    LOG = 20
    up = [[-1] * LOG for _ in range(n)]
    max_edge = [[0] * LOG for _ in range(n)]
    depth = [0] * n

    # DFS to build the tree structure and compute initial values
    visited = [False] * n

    def dfs(node, p, d):
        depth[node] = d
        visited[node] = True
        up[node][0] = p

        for i in range(1, LOG):
            if up[node][i-1] != -1:
                up[node][i] = up[up[node][i-1]][i-1]
                max_edge[node][i] = max(max_edge[node][i-1], max_edge[up[node][i-1]][i-1])

        for neighbor, weight in mst_adj[node]:
            if neighbor != p:
                dfs(neighbor, node, d + 1)

    dfs(0, -1, 0)

    results = []
    # Process original edges in the same order as input
    original_edges = {}
    for e, u, v, idx in edges:
        original_edges[idx] = (e, u, v)

    for idx in range(m):
        if idx not in mst_indices:
            _, u, v = original_edges[idx]

            # Find max edge weight on path between u and v in MST
            # First, make them same depth
            du, dv = depth[u], depth[v]

            if du < dv:
                u, v = v, u
            du, dv = depth[u], depth[v]

            max_w = 0
            if du > dv:
                for i in range(LOG - 1, -1, -1):
                    if depth[u] - (1 << i) >= dv:
                        max_w = max(max_w, max_edge[u][i])
