def max_flow_dinic(graph, source, sink, n):
    level = [0] * n

    def bfs():
        nonlocal level
        vis = [-1] * n
        vis[source] = 0
        queue = deque([source])
        while queue:
            u = queue.popleft()
            for v, cap, _ in graph[u]:
                if cap > 0 and vis[v] == -1:
                    vis[v] = vis[u] + 1
                    queue.append(v)
        return vis[sink] != -1

    def dfs(u, pushed, parent_edge):
        if pushed == 0 or u == sink:
            return pushed
        for i, (v, cap, rev_idx) in enumerate(graph[u]):
            if cap > 0 and level[v] == level[u] + 1:
                tr = dfs(v, min(pushed, cap), i)
                if tr > 0:
                    graph[u][i][1] -= tr
                    graph[v][rev_idx][1] += tr
                    return tr
        return 0

    flow = 0
    while bfs():
        level = [-1] * n
        level[source] = 0
        while True:
            pushed = dfs(source, float('inf'), None)
            if pushed == 0:
                break
            flow += pushed

    return flow

