def is_stable(n, cost, match):
    """Check if matching is stable - no two cities prefer each other over current partners"""
    for i in range(n):
        j = match[i]
        if i == j or j == -1:
            continue

        # Check all pairs (i, k) where k is not current partner
        for k in range(n):
            if k == i or k == j:
                continue

            if match[k] == -1 or match[k] == i:
                continue

            # Check if i and k would both prefer each other
            if cost[i][k] < cost[i][j] and cost[k][i] < cost[k][match[k]]:
                return False

    return True

