            dfs1(i)

    # Kosaraju's algorithm - second DFS for SCCs
    scc = [-1] * num_nodes
    scc_id = 0

    def dfs2(u):
        scc[u] = scc_id
        for v in rev_graph[u]:
            if scc[v] == -1:
                dfs2(v)
        scc_id += 1

    for i in range(num_nodes - 1, -1, -1):
        if scc[order[i]] == -1:
            dfs2(order[i])

    # Check satisfiability
    for i in range(m):
        if scc[2 * i] == scc[2 * i + 1]:
            return "NO"

    # Find satisfying assignment
    assignment = ['0'] * m
    for i in range(m):
        # If xi has smaller or equal SCC id than ~xi, set to 1
        if scc[2 * i] <= scc[2 * i + 1]:
            # Actually need the opposite - lower index means can be true
            if scc[2 * i] < scc[2 * i + 1]:
                assignment[i] = '1'
            else:
                assignment[i] = '1'

    result = "YES\n" + "".join(assignment)
    return result

