class SegmentTree:
    def __init__(self, arr):
        self.n = len(arr)
        self.min_tree = [0] * (4 * self.n)
        self.max_tree = [0] * (4 * self.n)
        self.lazy = [0] * (4 * self.n)
        self._build(arr, 0, 0, self.n - 1)

    def _build(self, arr, node, l, r):
        if l == r:
            self.min_tree[node] = self.max_tree[node] = arr[l]
            return
        mid = (l + r) // 2
        self._build(arr, 2*node+1, l, mid)
        self._build(arr, 2*node+2, mid+1, r)
        self.min_tree[node] = min(self.min_tree[2*node+1], self.min_tree[2*node+2])
        self.max_tree[node] = max(self.max_tree[2*node+1], self.max_tree[2*node+2])

    def _push(self, node, l, r):
        if self.lazy[node] != 0:
            mid = (l + r) // 2
            self._lazy_add(2*node+1, self.lazy[node])
            self._lazy_add(2*node+2, self.lazy[node])
            self.lazy[node] = 0

    def _lazy_add(self, node, val):
        self.lazy[node] += val
        self.min_tree[node] += val
        self.max_tree[node] += val

    def update(self, l, r, val):
        self._update(0, 0, self.n - 1, l, r, val)

    def _update(self, node, nl, nr, l, r, val):
        if l > nr or r < nl:
            return
        if l <= nl and nr <= r:
            self._lazy_add(node, val)
            return
        self._push(node, nl, nr)
        mid = (nl + nr) // 2
        self._update(2*node+1, nl, mid, l, r, val)
        self._update(2*node+2, mid+1, nr, l, r, val)
        self.min_tree[node] = min(self.min_tree[2*node+1], self.min_tree[2*node+2])
        self.max_tree[node] = max(self.max_tree[2*node+1], self.max_tree[2*node+2])

    def query_min(self, l, r):
        return self._query_min(0, 0, self.n - 1, l, r)

    def _query_min(self, node, nl, nr, l, r):
        if l > nr or r < nl:
            return float('inf')
        if l <= nl and nr <= r:
            return self.min_tree[node]
        self._push(node, nl, nr)
        mid = (nl + nr) // 2
        return min(self._query_min(2*node+1, nl, mid, l, r),
                  self._query_min(2*node+2, mid+1, nr, l, r))

    def query_max(self, l, r):
        return self._query_max(0, 0, self.n - 1, l, r)

    def _query_max(self, node, nl, nr, l, r):
        if l > nr or r < nl:
            return float('-inf')
        if l <= nl and nr <= r:
            return self.max_tree[node]
        self._push(node, nl, nr)
        mid = (nl + nr) // 2
        return max(self._query_max(2*node+1, nl, mid, l, r),
                  self._query_max(2*node+2, mid+1, nr, l, r))

    def get_global_min(self):
        return self.min_tree[0]

    def get_global_max(self):
        return self.max_tree[0]

def mult(matrix1, matrix2, mod):
    n1 = len(matrix1)
    m1 = len(matrix1[0])
    n2 = len(matrix2)
    m2 = len(matrix2[0])
    assert n1 == m2

    result = [[0] * m2 for _ in range(n1)]
    for i in range(n1):
        for j in range(m2):
            for k in range(m1):
                result[i][j] = (result[i][j] + matrix1[i][k] * matrix2[k][j]) % mod
    return result

def mat_pow(matrix, exp, mod):
    n = len(matrix)
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        result[i][i] = 1

    base = matrix
    while exp > 0:
        if exp % 2 == 1:
            result = mult(result, base, mod)
        base = mult(base, base, mod)
        exp //= 2
    return result

def mod_pow(base, exp, mod):
    result = 1
    base = base % mod
    while exp > 0:
        if exp % 2 == 1:
            result = (result * base) % mod
        base = (base * base) % mod
        exp //= 2
    return result

