    def is_collinear(a, b, c):
        # Determinant formula for collinearity
        return abs((b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])) < 1e-9

    def circumcenter(a, b, c):
        a0, a1 = a
        b0, b1 = b
        c0, c1 = c

        denom = 2 * (a0 * (b1 - c1) + b0 * (c1 - a1) + c0 * (a1 - b1))

        if abs(denom) < 1e-9:
            return None, None, None

        num_x = (a0**2 + a1**2) * (b1 - c1) + (b0**2 + b1**2) * (c1 - a1) + (c0**2 + c1**2) * (a1 - b1)
        num_y = (a0**2 + a1**2) * (c0 - b0) + (b0**2 + b1**2) * (a0 - c0) + (c0**2 + c1**2) * (b0 - a0)

        ox, oy = num_x / denom, num_y / denom

        # Distance from origin to circumcenter
        d = math.sqrt(ox**2 + oy**2)

        return ox, oy, d

    max_dist = -1.0

    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
