    min_y = (y1 + y2) / 2.0

    def check_radius(r):
        if r < D / 2.0:
            return False

        # For a circle through two points, center is on perpendicular bisector
        # Distance from midpoint to center: k' = sqrt(r^2 - D^2/4)
        try:
            k_prime = math.sqrt(max(0, r * r - D * D / 4.0))
        except:
            return False

        # Direction perpendicular to segment: (-dy, dx)
        # Unit perpendicular direction
        dir_x = -dy / D
        dir_y = dx / D

        # Two possible centers
        centers = [
            (min_x + k_prime * dir_x, min_y + k_prime * dir_y),
            (min_x - k_prime * dir_x, min_y - k_prime * dir_y)
        ]

