    for _ in range(q):
        queries.append(tuple(map(int, lines[idx].split())))
        idx += 1

    comp_id = [-1] * (n + 1)
    comp_gcd_list = []

    visited_global = [False] * (n + 1)

    for start_node in range(1, n + 1):
        if visited_global[start_node]:
            continue

        component_nodes = set()
        queue = [start_node]
        component_nodes.add(start_node)
        visited_local = {start_node}

        while queue:
            u = queue.pop(0)
            for v, _ in adj[u]:
                if v not in visited_local:
                    visited_local.add(v)
                    component_nodes.add(v)
                    queue.append(v)

        dist = {start_node: 0}
        parent = {start_node: -1}
        cycle_gcd = 0

        stack = [(start_node, 0, -1)]  # (node, distance_from_start, parent)

        while stack:
            u, d, p = stack.pop()

            for v, w in adj[u]:
                if v in dist:
                    cycle_len = d + w - dist[v]
                    cycle_gcd = gcd(cycle_gcd, cycle_len)
                elif v not in parent:
                    dist[v] = d + w
                    parent[v] = u
                    stack.append((v, d + w, u))

        comp_gcd_list.append(cycle_gcd)
        for node in component_nodes:
            comp_id[node] = len(comp_gcd_list) - 1

        for node in component_nodes:
            visited_global[node] = True

    results = []
    for v, s, t in queries:
        if s == 0:
