def is_prime(n):
    """Miller-Rabin primality test"""
    if n < 2:
        return False
    if n <= 3:
        return True
    if n % 2 == 0:
        return False

    # Write n-1 as 2^r * d
    r, d = 0, n - 1
    while d % 2 == 0:
        r += 1
        d //= 2

    # Witnesses for Miller-Rabin
    for a in [2, 3, 5, 7, 11, 13, 17, 19, 23]:
        if n <= a:
            break
        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            continue
        for _ in range(r - 1):
            x = pow(x, 2, n)
            if x == n - 1:
                break
        else:
            return False
    return True

def solution(input_data):
    """
    Find the largest base b (1 < b < x) such that there exists a rotatable number of length n in base b.

    A rotatable number of length n in base b exists if and only if there exists a prime p
    such that ord_p(b) = n (the multiplicative order of b mod p is n).
    This requires p = k*n + 1 for some integer k >= 1.

    We want the largest such b, so we search from x-1 down to 2.
    """
    n, x = map(int, input_data.strip().split())

    if n == 1:
        return '-1\n'

    # Find proper divisors of n (divisors < n)
    divisors = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    proper_divisors = sorted([d for d in divisors if d < n], reverse=True)
    if not proper_divisors:
        proper_divisors = []

    def check_order(b, p):
        """
        Check if ord_p(b) = n.
        This requires:
        1. b^n = 1 mod p
        2. For all proper divisors d of n, b^(n/d) != 1 mod p
        """
        if pow(b, n, p) != 1:
            return False
        for d in proper_divisors:
            if pow(b, n // d, p) == 1:
                return False
        return True

    # Try b from x-1 down to 2
    for b in range(x - 1, 1, -1):
        # For each b, find smallest prime p = k*n + 1 with ord_p(b) = n
        k = 1
        while True:
            p = k * n + 1
            if not is_prime(p):
                k += 1
                continue

            if check_order(b, p):
                return str(b) + '\n'

            # Safety check to prevent infinite loop
            # If p is getting too large (larger than maximum possible for this b)
            if p >= b * b * b:
                break
            k += 1
            if k > int(x / n) * 10:
                break

    return '-1\n'

